CREATE TABLE IF NOT EXISTS passenger_stalls (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, station_key TEXT NOT NULL, station_name TEXT NOT NULL, platform_label TEXT, description TEXT NOT NULL DEFAULT '', demo_label TEXT NOT NULL DEFAULT 'Demo listing', menu_json JSONB NOT NULL DEFAULT '[]'::jsonb, emoji TEXT NOT NULL DEFAULT '🥪', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());